import sys
from bisect import bisect_left

def minInsAndDel(N, M, A, B):
    map_B = {x: i for i, x in enumerate(B)}
    lis = []
    for x in A:
        if x in map_B:
            idx = map_B[x]
            pos = bisect_left(lis, idx)
            if pos == len(lis):
                lis.append(idx)
            else:
                lis[pos] = idx
    return N + M - 2 * len(lis)

def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    M = int(input[1])
    A = list(map(int, input[2:2+N]))
    B = list(map(int, input[2+N:2+N+M]))
    result = minInsAndDel(N, M, A, B)
    print(result)

if __name__ == "__main__":
    main()
